#!/bin/bash
# ===========================================================================
# testbed-ss.sh
#
# Helpers for the sockshop testbed (Blueprint-built variant).
#
# Background: sockshop manifests are NOT generated by this pipeline.
# Instead, they're compiled offline via Blueprint's plugins/kubernetes/
# (see TODO_SOCKSHOP.md for the build flow) and dropped into
# $SS_MANIFESTS_DIR as one subdir per pod (e.g. frontend-pod/,
# user-pod/, user-db-pod/, ...). Each contains a *-deployment.yaml
# and *-service.yaml. The Blueprint build is parameterized by
# BLUEPRINT_K8S_NAMESPACE at compile time and stamps that namespace
# into every manifest, so the compiled set already targets
# $SS_NAMESPACE.
#
# Functions exposed (sourced by stage3-eval.sh):
#   ss_deploy           <exp_dir>       -> kubectl apply -R the manifests
#   ss_teardown         <exp_dir>       -> reset nodeSelector/tolerations; no delete
#   ss_uninstall        <exp_dir>       -> kubectl delete namespace
#   ss_frontend_url     <target_node>   -> http://<node-ip>:<nodeport>
#   ss_deployment_for_service <svc>     -> human service name -> pod-suffixed deployment
#   ss_pod_for_deployment <deploy>      -> first Running pod name
# ===========================================================================

set -u

SS_NAMESPACE="${SS_NAMESPACE:-aggressor-ss}"
SS_MANIFESTS_DIR="${SS_MANIFESTS_DIR:-$STAGE3_EVAL_DIR/sockshop-manifests}"
# How long to wait for every sockshop deployment to report Available after
# apply. Sockshop services crash-loop until their dependencies are up, so the
# convergence can take a couple minutes on a cold deploy (image pulls + retry
# backoff). A timeout here means a genuinely broken testbed -- better to fail
# loud at deploy than drive an empty run.
SS_READY_TIMEOUT="${SS_READY_TIMEOUT:-300}"

# Human-friendly service name -> deployment name as our Blueprint build
# emits (each container becomes a separate pod named <ctr>_pod; our
# K8sName template helper then sanitizes the metadata.name to
# <ctr>-pod). The keys here use the hyphenated form that the user
# would write in their YAML configs (e.g. `service: user-db`).
declare -gA SS_SERVICE_TO_DEPLOYMENT=(
    [frontend]=frontend-pod
    [user]=user-pod
    [cart]=cart-pod
    [order]=order-pod
    [payment]=payment-pod
    [shipping]=shipping-pod
    [catalogue]=catalogue-pod
    [user-db]=user-db-pod
    [cart-db]=cart-db-pod
    [order-db]=order-db-pod
    [shipping-db]=shipping-db-pod
    [catalogue-db]=catalogue-db-pod
)

# ---------------------------------------------------------------------------
# ss_deployment_for_service <human-service-name>
# ---------------------------------------------------------------------------
ss_deployment_for_service() {
    local svc="$1"
    local mapped="${SS_SERVICE_TO_DEPLOYMENT[$svc]:-}"
    if [[ -z "$mapped" ]]; then
        echo "ERROR [testbed-ss]: unknown SS service '$svc'" >&2
        echo "       Known: ${!SS_SERVICE_TO_DEPLOYMENT[*]}" >&2
        return 1
    fi
    echo "$mapped"
}

# ---------------------------------------------------------------------------
# ss_deploy <exp_dir>
#
# Idempotent: kubectl apply -R picks up every YAML under SS_MANIFESTS_DIR
# (each pod has its own subdir with *-deployment.yaml and *-service.yaml).
# Creates the namespace if it doesn't exist.
#
# The Blueprint build was parameterized by BLUEPRINT_K8S_NAMESPACE, so the
# manifests already contain `metadata.namespace: $SS_NAMESPACE`. We pass
# -n as a belt-and-suspenders override in case someone re-stashes
# manifests built with a different namespace.
# ---------------------------------------------------------------------------
ss_deploy() {
    local exp_dir="$1"
    local log_prefix="[testbed-ss]"

    if [[ ! -d "$SS_MANIFESTS_DIR" ]]; then
        echo "ERROR $log_prefix: SS_MANIFESTS_DIR not found at '$SS_MANIFESTS_DIR'" >&2
        echo "       Run the Blueprint sockshop build (see TODO_SOCKSHOP.md) and" >&2
        echo "       drop the generated build/*_pod/ subdirs into the path above." >&2
        return 1
    fi

    # Sanity: at least one deployment.yaml present?
    if ! ls "$SS_MANIFESTS_DIR"/*/*-deployment.yaml >/dev/null 2>&1; then
        echo "ERROR $log_prefix: no *-deployment.yaml files under $SS_MANIFESTS_DIR/*/" >&2
        echo "       Expected layout: $SS_MANIFESTS_DIR/<pod-name>/<pod-name>-{deployment,service}.yaml" >&2
        return 1
    fi

    echo "$log_prefix Creating namespace '$SS_NAMESPACE' (no-op if exists)"
    kubectl create namespace "$SS_NAMESPACE" --dry-run=client -o yaml \
        | kubectl apply -f - >> "$exp_dir/logs/testbed-ss.log" 2>&1

    echo "$log_prefix Applying sockshop manifests from $SS_MANIFESTS_DIR into $SS_NAMESPACE"
    kubectl apply -R -f "$SS_MANIFESTS_DIR/" -n "$SS_NAMESPACE" \
        >> "$exp_dir/logs/testbed-ss.log" 2>&1 || {
            echo "ERROR $log_prefix: kubectl apply failed; see $exp_dir/logs/testbed-ss.log" >&2
            return 1
        }

    # Gate on readiness. kubectl apply returns as soon as the objects are
    # accepted, not when pods serve -- without this wait a fully crash-looped
    # sockshop (e.g. missing inter-service *_DIAL_ADDR env) sails through and the
    # run drives an unreachable frontend ("connection refused"), producing a
    # "COMPLETE" experiment with zero sockshop load. Fail loud instead.
    echo "$log_prefix Waiting up to ${SS_READY_TIMEOUT}s for all sockshop deployments to become Available"
    if ! kubectl wait --for=condition=Available deployment --all \
            -n "$SS_NAMESPACE" --timeout="${SS_READY_TIMEOUT}s" \
            >> "$exp_dir/logs/testbed-ss.log" 2>&1; then
        echo "ERROR $log_prefix: sockshop deployments did not all become Available within ${SS_READY_TIMEOUT}s" >&2
        echo "       Inspect: kubectl -n $SS_NAMESPACE get pods" >&2
        echo "       Likely a crash-looping service -- check its logs, e.g.:" >&2
        echo "                kubectl -n $SS_NAMESPACE logs deploy/frontend-pod" >&2
        kubectl -n "$SS_NAMESPACE" get pods >> "$exp_dir/logs/testbed-ss.log" 2>&1 || true
        return 1
    fi

    return 0
}

# ---------------------------------------------------------------------------
# ss_scale_replicas <n> [exp_dir]
#
# Scale every sockshop APP deployment to <n> replicas, skipping the *-db
# datastores (scaling stateful singletons would break them). No-op for n<=1.
# Async; new pods come up during the victim deploy + warmup. The pinned
# aggressor SS service gets its replicas placed on target_node; the rest add
# upstream throughput.
# ---------------------------------------------------------------------------
ss_scale_replicas() {
    local n="$1" exp_dir="${2:-}"
    [[ "$n" =~ ^[0-9]+$ ]] || return 0
    (( n <= 1 )) && return 0
    local log=/dev/null
    [[ -n "$exp_dir" ]] && log="$exp_dir/logs/testbed-ss.log"
    local svc deploy count=0
    for svc in "${!SS_SERVICE_TO_DEPLOYMENT[@]}"; do
        case "$svc" in *-db) continue ;; esac   # skip cart-db / order-db / ... datastores
        deploy="${SS_SERVICE_TO_DEPLOYMENT[$svc]}"
        kubectl -n "$SS_NAMESPACE" scale deployment "$deploy" --replicas="$n" \
            >> "$log" 2>&1 && (( count++ )) || true
    done
    echo "[testbed-ss] Scaled $count sockshop app deployments to $n replicas"
}

# ---------------------------------------------------------------------------
# ss_teardown <exp_dir>
#
# Soft reset: strip nodeSelector + tolerations from every sockshop
# deployment so the next experiment starts from clean scheduling state.
# Leaves the deployments in place (back-to-back experiments stay fast).
# ---------------------------------------------------------------------------
ss_teardown() {
    local exp_dir="$1"
    echo "[testbed-ss] Resetting SS deployments to pre-experiment scheduling state"

    local svc deploy
    for svc in "${!SS_SERVICE_TO_DEPLOYMENT[@]}"; do
        deploy="${SS_SERVICE_TO_DEPLOYMENT[$svc]}"
        if ! kubectl -n "$SS_NAMESPACE" get deployment "$deploy" >/dev/null 2>&1; then
            continue
        fi
        kubectl -n "$SS_NAMESPACE" patch deployment "$deploy" --type='merge' -p '{
          "spec": { "template": { "spec": {
            "nodeSelector": null,
            "tolerations":  null
          }}}
        }' >> "$exp_dir/logs/testbed-ss.log" 2>&1 || true
    done
    return 0
}

# ---------------------------------------------------------------------------
# ss_uninstall <exp_dir>
#
# Full reset: delete the namespace, which cascades to every sockshop
# resource. Only called when the user passes --uninstall-ss to
# stage3-eval.sh (would need to be added to the orchestrator's flags).
# ---------------------------------------------------------------------------
ss_uninstall() {
    local exp_dir="$1"
    echo "[testbed-ss] Deleting namespace '$SS_NAMESPACE' (cascades to all sockshop resources)"
    kubectl delete namespace "$SS_NAMESPACE" --ignore-not-found \
        >> "$exp_dir/logs/testbed-ss.log" 2>&1 || true
}

# ---------------------------------------------------------------------------
# ss_frontend_url <target_node>
#
# Promotes the sockshop frontend service to NodePort if it isn't
# already, then echoes the wrk2 target URL (http://<node-ip>:<nodeport>).
# ---------------------------------------------------------------------------
ss_frontend_url() {
    local target_node="$1"
    local svc="frontend-pod"

    local svc_type
    svc_type=$(kubectl -n "$SS_NAMESPACE" get svc "$svc" \
        -o jsonpath='{.spec.type}' 2>/dev/null || echo "")
    if [[ "$svc_type" != "NodePort" && "$svc_type" != "LoadBalancer" ]]; then
        kubectl -n "$SS_NAMESPACE" patch svc "$svc" \
            -p '{"spec":{"type":"NodePort"}}' >/dev/null 2>&1 || true
    fi

    local node_port
    node_port=$(kubectl -n "$SS_NAMESPACE" get svc "$svc" \
        -o jsonpath='{.spec.ports[0].nodePort}' 2>/dev/null)
    if [[ -z "$node_port" ]]; then
        echo "ERROR [testbed-ss]: failed to resolve $svc NodePort in $SS_NAMESPACE" >&2
        return 1
    fi

    local node_ip
    node_ip=$(kubectl get node "$target_node" \
        -o jsonpath='{.status.addresses[?(@.type=="InternalIP")].address}' 2>/dev/null)
    if [[ -z "$node_ip" ]]; then
        node_ip=$(kubectl get node "$target_node" \
            -o jsonpath='{.status.addresses[?(@.type=="ExternalIP")].address}' 2>/dev/null)
    fi
    if [[ -z "$node_ip" ]]; then
        echo "ERROR [testbed-ss]: failed to resolve IP for node '$target_node'" >&2
        return 1
    fi
    echo "http://${node_ip}:${node_port}"
}

# ---------------------------------------------------------------------------
# ss_pod_for_deployment <deployment-name>
#
# The Blueprint kubernetes plugin labels every pod with
# `blueprint.service: <pod-name>`. The pod name is what we look up by.
# ---------------------------------------------------------------------------
ss_pod_for_deployment() {
    local deploy="$1"
    kubectl -n "$SS_NAMESPACE" get pods \
        -l "blueprint.service=$deploy" \
        --field-selector=status.phase=Running \
        -o jsonpath='{.items[0].metadata.name}' 2>/dev/null || echo ""
}
